import{_ as t,a,c as o,ac as r}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"网络技术教程","description":"从网络需求、架构到运维理解网络技术，附版本待确认说明与主题导读。","frontmatter":{"title":"网络技术教程","description":"从网络需求、架构到运维理解网络技术，附版本待确认说明与主题导读。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"书籍导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"书单 · 计算机与软件工程 · 网络与操作系统","summary":"从网络需求、架构到运维理解网络技术，附版本待确认说明与主题导读。","status":"active","related":[{"title":"计算机网络基础教程（第3版）","link":"/life/personal/books/computing/network-foundations","kind":"书籍导读","scope":"general","audience":"general"},{"title":"网络简介实验手册","link":"/life/personal/books/computing/network-lab","kind":"书籍导读","scope":"general","audience":"general"},{"title":"网络互连技术","link":"/life/personal/books/computing/internetworking","kind":"书籍导读","scope":"general","audience":"general"},{"title":"思科网络技术学院教程 路由和交换基础实验手册","link":"/life/personal/books/computing/cisco-routing-switching-lab","kind":"书籍导读","scope":"general","audience":"general"},{"title":"计算机网络原理","link":"/life/personal/books/computing/network-principles","kind":"书籍导读","scope":"general","audience":"general"},{"title":"Red Hat Enterprise Linux 6.5 系统管理","link":"/life/personal/books/computing/rhel-65","kind":"书籍导读","scope":"general","audience":"general"},{"title":"Linux命令行与shell脚本编程大全（第4版）","link":"/life/personal/books/computing/linux-shell","kind":"书籍导读","scope":"general","audience":"general"}],"prev":{"text":"网络互连技术","link":"/life/personal/books/computing/internetworking"},"next":{"text":"思科网络技术学院教程 路由和交换基础实验手册","link":"/life/personal/books/computing/cisco-routing-switching-lab"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"网络互连技术","link":"/life/personal/books/computing/internetworking"},"next":{"text":"思科网络技术学院教程 路由和交换基础实验手册","link":"/life/personal/books/computing/cisco-routing-switching-lab"}},"headers":[],"relativePath":"life/personal/books/computing/network-technology.md","filePath":"life/personal/books/computing/network-technology.md"}'),n={name:"life/personal/books/computing/network-technology.md"};function i(l,e,s,d,c,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="网络技术教程" tabindex="-1">网络技术教程 <a class="header-anchor" href="#网络技术教程" aria-label="Permalink to &quot;网络技术教程&quot;">​</a></h1><p><a href="./../overview">返回分类书单</a></p><p><strong>分类：计算机与软件工程 / 网络与操作系统</strong></p><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p>这本书在书单中可作为网络技术的综合入口：把局域网、广域网、无线连接、网络服务和运维放进一张完整地图。适合已经接触一些零散概念，但希望理解它们在网络建设中如何配合的读者。</p><p>阅读目标是能够解释一个网络方案：谁需要访问什么，业务量怎样变化，故障时如何发现问题，以及哪些边界必须有明确的访问规则。</p><h2 id="版本说明" tabindex="-1">版本说明 <a class="header-anchor" href="#版本说明" aria-label="Permalink to &quot;版本说明&quot;">​</a></h2><p><strong>版本待确认。</strong> “网络技术教程”存在同名或近名教材，目前没有作者和 ISBN。以下为本站主题导读，不是原书目录；不据此声称原书包含特定厂商命令或认证内容。</p><h2 id="作者与背景" tabindex="-1">作者与背景 <a class="header-anchor" href="#作者与背景" aria-label="Permalink to &quot;作者与背景&quot;">​</a></h2><p>《网络技术教程》的作者、出版社和版次仍待确认。书名可能被简称，检索到的“计算机网络技术教程”或“Cisco网络技术教程”不能直接替代。本页不借用近名书作者的资历；需核对完整封面题名、ISBN 与目录侧重后，才能评价本册的教学背景和技术适用范围。</p><h2 id="目标读者" tabindex="-1">目标读者 <a class="header-anchor" href="#目标读者" aria-label="Permalink to &quot;目标读者&quot;">​</a></h2><p>适合学过零散网络概念、希望建立建设与维护全景的人。应用开发者可以先梳理基础服务依赖；需要设计真实网络的人，还要补充流量需求、物理环境和故障恢复约束。</p><h2 id="章节介绍" tabindex="-1">章节介绍 <a class="header-anchor" href="#章节介绍" aria-label="Permalink to &quot;章节介绍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>导读主题</th><th>阅读关注点</th></tr></thead><tbody><tr><td>需求与拓扑</td><td>从用户、终端数量和业务关系推导网络结构，避免先选设备再寻找用途。</td></tr><tr><td>传输介质与布线</td><td>认识铜缆、光纤和无线传输的限制，区分接口速率与实际使用体验。</td></tr><tr><td>局域网技术</td><td>理解以太网交换、广播域和 VLAN，把逻辑隔离落实到拓扑中。</td></tr><tr><td>无线网络</td><td>关注覆盖、干扰、认证与漫游，理解信号强度并不是体验的唯一因素。</td></tr><tr><td>广域连接</td><td>比较专线、互联网接入和隧道的用途，分析可用性与成本约束。</td></tr><tr><td>网络基础服务</td><td>理解 DHCP、DNS 和时间同步为何影响整个网络的运行。</td></tr><tr><td>安全与访问边界</td><td>以业务流为单位整理权限，理解认证、授权、加密与审计的区别。</td></tr><tr><td>监测与维护</td><td>记录设备状态、流量变化和配置版本，形成能够追溯的维护过程。</td></tr></tbody></table><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><p>以下为本站阅读评析，用可实践的阅读目标表达收获，不代表书单提供者已经读完、任职或完成相应项目。版本未明时，评析只针对本页明确标注的主题或参考版本。</p><h3 id="金句摘抄或阅读提炼" tabindex="-1">金句摘抄或阅读提炼 <a class="header-anchor" href="#金句摘抄或阅读提炼" aria-label="Permalink to &quot;金句摘抄或阅读提炼&quot;">​</a></h3><blockquote><p>先问谁要访问什么，再问需要哪台设备。</p></blockquote><p>这是本站原创阅读提炼，不是原书引文；没有可核对页码的原文不作逐字摘抄。</p><h3 id="个人收获" tabindex="-1">个人收获 <a class="header-anchor" href="#个人收获" aria-label="Permalink to &quot;个人收获&quot;">​</a></h3><p>尝试给自己的开发环境写一页网络说明：终端与服务的位置、地址段、DNS 和 DHCP 的依赖、访问边界与诊断入口。让另一位读者据此找到问题，可以检验知识是否已经转化为可交接的方案。</p><h3 id="客观评价与阅读建议" tabindex="-1">客观评价与阅读建议 <a class="header-anchor" href="#客观评价与阅读建议" aria-label="Permalink to &quot;客观评价与阅读建议&quot;">​</a></h3><p>综合教程容易覆盖广而解释浅，也容易随着设备与无线技术演进而过时；本册具体覆盖范围待目录确认。建议每个名词都回答用途、前提、代价与故障现象四个问题，避免只增加术语数量。</p><p><strong>推荐语（本站原创，非原书引用）：</strong> 推荐给想把零散知识整理成网络全景的人：能解释一份方案的取舍，比能列出很多设备型号更有帮助。</p><h2 id="来源与核对入口" tabindex="-1">来源与核对入口 <a class="header-anchor" href="#来源与核对入口" aria-label="Permalink to &quot;来源与核对入口&quot;">​</a></h2><ul><li>书名来自本次书单；准确的作者、版本与目录待纸书核对。</li><li><a href="https://www.ieee802.org/" target="_blank" rel="noopener noreferrer">IEEE 802 标准工作组</a>：以太网与无线网络标准的补充入口。</li><li><a href="https://www.netacad.com/" target="_blank" rel="noopener noreferrer">Cisco Networking Academy</a>：网络技术学习资源，不作为本书身份或目录的证明。</li></ul>',26)])])}const k=t(n,[["render",i]]);export{u as __pageData,k as default};
